builder.Services.AddScoped<IOrderRepository, OrderRepository>();
builder.Services.AddSingleton<ICacheService, CacheService>();

// CacheService takes IOrderRepository in its constructor
// -> throws InvalidOperationException when the app starts

public interface IOrderProcessorFactory
{
    OrderProcessor Create(IOrderRepository repository);
}

public class CacheService
{
    private readonly IOrderProcessorFactory _factory;

    public CacheService(IOrderProcessorFactory factory)
    {
        _factory = factory;
    }

    public async Task RefreshAsync()
    {
        // repository is resolved per-call, not stored in the singleton
        using var scope = _serviceProvider.CreateScope();
        var repo = scope.ServiceProvider.GetRequiredService<IOrderRepository>();
        var processor = _factory.Create(repo);
        await processor.RebuildCacheAsync();
    }
}
